/* Urgency/Flashing Styles for accessibility and urgent alerts */
.urgency-error {
  animation: flash-red 1s infinite;
}

.urgency-warning {
  animation: flash-yellow 1.5s infinite;
}

.urgency-success {
  animation: flash-green 2s infinite;
}

@keyframes flash-red {
  0%, 100% { border-color: rgba(239, 68, 68, 0.2); box-shadow: 0 0 0 rgba(239, 68, 68, 0); }
  50% { border-color: rgba(239, 68, 68, 1); box-shadow: 0 0 15px rgba(239, 68, 68, 0.5); }
}

@keyframes flash-yellow {
  0%, 100% { border-color: rgba(245, 158, 11, 0.2); box-shadow: 0 0 0 rgba(245, 158, 11, 0); }
  50% { border-color: rgba(245, 158, 11, 1); box-shadow: 0 0 15px rgba(245, 158, 11, 0.5); }
}

@keyframes flash-green {
  0%, 100% { border-color: rgba(34, 197, 94, 0.2); box-shadow: 0 0 0 rgba(34, 197, 94, 0); }
  50% { border-color: rgba(34, 197, 94, 1); box-shadow: 0 0 15px rgba(34, 197, 94, 0.5); }
}

.urgency-text-error {
  animation: text-flash-red 1s infinite;
}
@keyframes text-flash-red {
  0%, 100% { color: #EF4444; }
  50% { color: #FCA5A5; }
}

/* Pulsing background for really critical stuff */
.urgency-critical-bg {
  animation: bg-flash-red 0.8s infinite;
}

@keyframes bg-flash-red {
  0%, 100% { background-color: rgba(239, 68, 68, 0.1); }
  50% { background-color: rgba(239, 68, 68, 0.4); }
}
